contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint that takes parameters and performs the test
    function run(uint sendAmount, uint withdrawAmount, bytes calldata data) public payable {
        // Ensure this contract has enough balance to send to c when testing fallback and balance invariants
        require(address(this).balance >= sendAmount);

        // Record balances before interactions
        uint cBalanceBefore = address(c).balance;
        uint selfBalanceBefore = address(this).balance;

        // Send Ether to C's fallback by calling with value; this will increment depositsCount
        // This call is made by InvMutTest (msg.sender for c will be this contract), which is NOT the owner of c
        // so later withdraw attempts from this contract should revert.
        // Use low-level call to trigger fallback (as fallback is payable and accepts any calldata)
        (bool okSend, ) = address(c).call{value: sendAmount}(data);
        // send to fallback should succeed (fallback payable doesn't revert)
        // but we do not assert on okSend here — we only use balances recorded

        // Attempt to withdraw from c as non-owner. According to contract C, withdraw should revert via onlyOwner.
        bool withdrewReverted;
        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Attempt withdrawAll as non-owner as well
        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // Read balances after
        uint cBalanceAfter = address(c).balance;
        uint selfBalanceAfter = address(this).balance;

        // General rule: when called from a non-owner account (this contract), withdraw and withdrawAll must revert
        // and irrespective of these calls, the balances must not have decreased for c nor increased for this contract
        // (i.e., non-owner cannot extract funds). We assert that at least withdraw reverted, withdrawAll reverted,
        // and that c's balance did not decrease and this contract's balance did not increase compared to before the withdraw attempts.
        assert(withdrewReverted && withdrewAllReverted && cBalanceAfter >= cBalanceBefore && selfBalanceAfter <= selfBalanceBefore);
    }

    // allow receiving Ether so calls that transfer back (if any) can be handled
    receive() external payable {}
}

