contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: when this contract (the owner) sends Ether to c via fallback, then withdrawing the same amount
    // using withdraw(uint) and withdrawAll() should succeed (not revert) and move the Ether back here.
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");
        // depositAmount must be non-zero to exercise balance changes
        require(depositAmount > 0, "depositAmount must be > 0");

        // initial observations
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;
        uint beforeDepositsCount = c.depositsCount();

        // send Ether to c to trigger fallback increment; since this contract is owner, fallback increments depositsCount
        c.f{value: depositAmount}();

        uint afterDepositC = address(c).balance;
        uint afterDepositMe = address(this).balance;
        uint afterDepositsCount = c.depositsCount();

        // sanity: c got the funds and depositsCount incremented by 1
        // Now attempt a withdraw of withdrawAmount (capped by contract balance to avoid revert from transfer)
        uint available = address(c).balance;
        uint toWithdraw = withdrawAmount;
        if (toWithdraw > available) {
            toWithdraw = available;
        }

        bool revertedWithdraw;
        try c.withdraw(toWithdraw) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        uint afterWithdrawC = address(c).balance;
        uint afterWithdrawMe = address(this).balance;

        // then call withdrawAll to drain remaining balance
        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        uint finalC = address(c).balance;
        uint finalMe = address(this).balance;

        // ASSERTION (single general rule):
        // Because this contract deployed C, it is the owner. Therefore withdrawals invoked here must not revert,
        // and the total Ether moved from c to this contract after withdraw + withdrawAll equals the Ether that was in c after deposit.
        assert(
            // owner should be able to withdraw: neither call should revert
            revertedWithdraw == false && revertedWithdrawAll == false
            // final C balance equals zero (withdrawAll drains remaining funds)
            && finalC == 0
            // the net increase in this contract's balance equals the net decrease in c's balance from its value after deposit
            && (finalMe - afterDepositMe) == (afterDepositC - finalC)
            // depositsCount must have increased by exactly 1 due to the single fallback deposit
            && afterDepositsCount == beforeDepositsCount + 1
        );
    }

    // allow receiving Ether from c.transfer
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This contract is the deployer of c, so it is the owner. We deposit Ether into c by calling it with empty calldata
    // to trigger the fallback, then call withdraw(amount) and withdrawAll() and assert both succeed and that all
    // Ether present after the deposit is moved back to this contract; also depositsCount increments by 1.
    function run(uint depositAmount, uint withdrawAmount) public payable {
        // ensure we have funds to deposit
        require(address(this).balance >= depositAmount, "insufficient balance to fund deposit");
        require(depositAmount > 0, "depositAmount must be > 0 to exercise fallback");

        // observe before-state
        uint beforeC = address(c).balance;
        uint beforeMe = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        // send Ether to c with empty calldata to trigger fallback (top-level call that changes c)
        // note: call must be done as a top-level statement
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "deposit call failed");

        uint afterDepositC = address(c).balance;
        uint afterDepositMe = address(this).balance;
        uint afterDeposits = c.depositsCount();

        // cap withdrawAmount to avoid needless revert due to transfer amount > balance
        uint toWithdraw = withdrawAmount;
        if (toWithdraw > address(c).balance) {
            toWithdraw = address(c).balance;
        }

        bool revertedWithdraw;
        try c.withdraw(toWithdraw) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        uint afterWithdrawC = address(c).balance;
        uint afterWithdrawMe = address(this).balance;

        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        uint finalC = address(c).balance;
        uint finalMe = address(this).balance;

        // General rule assertion:
        // - fallback increased depositsCount by exactly 1
        // - neither withdraw nor withdrawAll reverted (owner calls should succeed)
        // - the combined effect of withdraw and withdrawAll moved all Ether that was in c after deposit back to this contract
        assert(
            afterDeposits == beforeDeposits + 1
            && revertedWithdraw == false
            && revertedWithdrawAll == false
            && (finalMe - afterDepositMe) == (afterDepositC - finalC)
        );
    }

    // accept Ether forwarded by C.transfer
    receive() external payable { }
}

