contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that when this (the owner) calls withdraw/withdrawAll/sendMoney or triggers fallback,
    // the observable effects are consistent: successful withdraw/sendMoney reduces address(c).balance
    // by at most the requested amount and increases address(this).balance accordingly; fallback increments depositsCount.
    // Parameters choose which action and amounts/data to use.
    function run(uint8 action, uint value, address target, bytes calldata data) public payable {
        // action: 0 = call fallback by sending value to c, 1 = withdraw(value), 2 = withdrawAll(), 3 = sendMoney(target,value,data)
        require(action <= 3);
        // ensure this test contract has enough balance to send value to c when needed
        if (action == 0) {
            require(address(this).balance >= value);
            // record before
            uint beforeBalC = address(c).balance;
            uint beforeDeposits = c.depositsCount();

            // call fallback by sending ether with empty calldata
            // top-level state-changing call
            (bool ok, ) = address(c).call{value: value}("");
            // now read after values
            uint afterBalC = address(c).balance;
            uint afterDeposits = c.depositsCount();

            // If the call succeeded, contract balance must have increased by value and depositsCount incremented by 1
            // If it failed, neither balance nor depositsCount should have changed
            assert( (ok && afterBalC == beforeBalC + value && afterDeposits == beforeDeposits + 1) || (!ok && afterBalC == beforeBalC && afterDeposits == beforeDeposits) );
            return;
        }

        // For other actions this contract is the owner (since it deployed c), so calls should not revert.
        // Record balances before
        uint beforeBalC2 = address(c).balance;
        uint beforeBalThis = address(this).balance;

        bool reverted;
        if (action == 1) {
            // withdraw(value)
            try c.withdraw(value) {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint afterBalC2 = address(c).balance;
            uint afterBalThis = address(this).balance;
            // If not reverted, c's balance decreased by at most value and this contract's balance increased by that same amount
            // (transfer may send fewer if c had less than value available)
            uint dec = beforeBalC2 >= afterBalC2 ? beforeBalC2 - afterBalC2 : 0;
            assert(!reverted == (afterBalThis >= beforeBalThis && dec == afterBalThis - beforeBalThis));
            return;
        }
        if (action == 2) {
            // withdrawAll()
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint afterBalC2b = address(c).balance;
            uint afterBalThisb = address(this).balance;
            uint decb = beforeBalC2 >= afterBalC2b ? beforeBalC2 - afterBalC2b : 0;
            // If not reverted, this contract should receive exactly the decrease of c
            assert(!reverted == (afterBalThisb >= beforeBalThis && decb == afterBalThisb - beforeBalThis));
            return;
        }
        if (action == 3) {
            // sendMoney(target,value,data)
            try c.sendMoney(target, value, data) {
                reverted = false;
            } catch {
                reverted = true;
            }
            uint afterBalC3 = address(c).balance;
            uint afterBalThis3 = address(this).balance;
            uint dec3 = beforeBalC2 >= afterBalC3 ? beforeBalC2 - afterBalC3 : 0;
            // If call succeeded, c's balance decreased by at most value and this contract's balance unchanged (unless target==this)
            // We assert that decrease matches any increase to this contract (covers case target==this)
            assert(!reverted == (afterBalThis3 >= beforeBalThis ? dec3 == afterBalThis3 - beforeBalThis : dec3 == 0));
            return;
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // action: 0 = send Ether to trigger fallback (empty calldata)
    //         1 = withdraw(value)
    //         2 = withdrawAll()
    //         3 = sendMoney(target, value, data)
    function run(uint8 action, uint value, address target, bytes calldata data) public payable {
        require(action <= 3);

        // We will record before values, perform exactly one top-level state-changing call on c, then read after values.
        uint beforeBalC = address(c).balance;
        uint beforeBalThis = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        bool ok;
        // All state-changing interactions must be top-level calls.
        if (action == 0) {
            require(address(this).balance >= value);
            (ok, ) = address(c).call{value: value}("");
        } else if (action == 1) {
            // withdraw(value)
            try c.withdraw(value) {
                ok = true;
            } catch {
                ok = false;
            }
        } else if (action == 2) {
            // withdrawAll()
            try c.withdrawAll() {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // sendMoney(target,value,data)
            try c.sendMoney(target, value, data) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        uint afterBalC = address(c).balance;
        uint afterBalThis = address(this).balance;
        uint afterDeposits = c.depositsCount();

        // Single general assertion covering all actions:
        // - For fallback (action 0): if call succeeded then c balance increased by value and depositsCount increased by 1; if failed neither changed.
        // - For withdraw (1) and withdrawAll (2): if call succeeded then decrease of c balance equals increase of this contract's balance; if failed neither changed.
        // - For sendMoney (3): if call succeeded then c balance decreased by at most value, and any increase of this contract equals that decrease; if failed neither changed.
        assert(
            (action == 0 && (
                (ok && afterBalC == beforeBalC + value && afterDeposits == beforeDeposits + 1)
                || (!ok && afterBalC == beforeBalC && afterDeposits == beforeDeposits)
            ))
            || ((action == 1 || action == 2) && (
                (ok && beforeBalC >= afterBalC && afterBalThis - beforeBalThis == beforeBalC - afterBalC)
                || (!ok && afterBalC == beforeBalC && afterBalThis == beforeBalThis)
            ))
            || (action == 3 && (
                (ok && beforeBalC >= afterBalC && beforeBalC - afterBalC <= value && afterBalThis - beforeBalThis == (beforeBalC - afterBalC))
                || (!ok && afterBalC == beforeBalC && afterBalThis == beforeBalThis)
            ))
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // action: 0 = send Ether to trigger fallback (empty calldata)
    //         1 = withdraw(value)
    //         2 = withdrawAll()
    //         3 = sendMoney(target, value, data)
    function run(uint8 action, uint value, address target, bytes calldata data) public payable {
        require(action <= 3);

        // record before state (allowed: public getters and address(c).balance)
        uint beforeBalC = address(c).balance;
        uint beforeBalThis = address(this).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;

        // Perform exactly one top-level state-changing interaction on c.
        if (action == 0) {
            // call fallback via low-level call to send Ether with empty calldata
            require(address(this).balance >= value);
            // low-level call is not to c.f(), so we must invoke via address(c).call: allowed as it's a call to c's address
            // It is still a top-level statement and will change c when successful.
            (bool ok, ) = address(c).call{value: value}("\x00");
            reverted = !ok;
        } else if (action == 1) {
            try c.withdraw(value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (action == 2) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // action == 3
            try c.sendMoney(target, value, data) {
                reverted = false;
            } catch {
                reverted = true;
            }
