contract InvMutTest {
    C c;
    address other;

    constructor(C _c) { c = _c; other = address(0x1234); }

    // We accept three inputs: attemptWithdrawAll (whether to call withdrawAll),
    // attemptWithdrawAmount (whether to call withdraw with an amount),
    // amount (value to send with withdraw call if used).
    // The function is payable to allow sending ether when making fallback-invoking calls to c.
    function run(bool callWithdrawAll, bool callWithdrawAmount, uint amount) public payable {
        require(true);

        // Ensure this test contract (the owner of c) has some ether to work with if needed
        // but do not rely on msg.value. If we need to send ether to c via fallback, we use c.f{value: ...}.
        // Record before-values
        uint beforeBalanceC = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // 1) As owner (this contract), send arbitrary ether to c's fallback by calling with value
        // This should increase depositsCount by 1 when value > 0
        if (msg.value > 0) {
            // ensure we have the ether in this contract (msg.value provided by the caller)
            // Forward the ether to c so fallback increments depositsCount
            // Top-level state-changing call
            c.f{value: msg.value}();
        }

        // Record mid-values
        uint midBalanceC = address(c).balance;
        uint midDeposits = c.depositsCount();

        // 2) Try withdrawAll as owner OR simulate a non-owner call via a low-level call from an external address
        bool withdrawAllReverted = false;
        if (callWithdrawAll) {
            // Owner call (should succeed)
            try c.withdrawAll() {
                withdrawAllReverted = false;
            } catch {
                withdrawAllReverted = true;
            }
        }

        // 3) Try withdraw(amount) as owner
        bool withdrawReverted = false;
        if (callWithdrawAmount) {
            try c.withdraw(amount) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        }

        // 4) Now attempt to call withdraw from a non-owner by making a low-level call as `other`.
        // We cannot change msg.sender in Solidity here, but we can simulate this by calling c.sendMoney
        // which has onlyOwner so will revert when invoked by non-owner; however sendMoney is onlyOwner too.
        // Instead, we perform a direct external call via address(c).call from this contract specifying
        // the calldata for withdraw(uint256) but this still has msg.sender == this contract (owner), so
        // to check non-owner behaviour we rely on the fact that onlyOwner prevents non-owner external callers,
        // and so the general rule will assert owner-only access from this contract's perspective.

        // Read after-values
        uint afterBalanceC = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule asserted:
        // - depositsCount increased by exactly 1 iff msg.value > 0 and fallback was invoked (owner sending value)
        // - withdraw/withdrawAll when invoked by owner do not increase depositsCount
        // - withdraw/withdrawAll cannot increase c.balance (they can only decrease it or be no-op), so afterBalanceC <= midBalanceC
        // - If owner calls withdraw/withdrawAll and there was balance available, the call should not revert (we conservatively assert that owner calls do not revert)

        assert(
            // depositsCount change condition
            (msg.value == 0 ? afterDeposits == beforeDeposits : afterDeposits == beforeDeposits + 1)
            // withdraws do not increase depositsCount
            && afterDeposits >= midDeposits
            // contract balance never increases as a result of withdraw/withdrawAll calls from owner
            && afterBalanceC <= midBalanceC
            // owner-invoked withdraw/withdrawAll should not revert when called (property of owner)
            && (!callWithdrawAll || withdrawAllReverted == false)
            && (!callWithdrawAmount || withdrawReverted == false)
        );
    }

    // allow receiving ether
    receive() external payable {}
}

