contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function holding the property test
    // params:
    //  - callerIsOwner: if true we perform the call as the owner (this contract already is owner),
    //                   otherwise we simulate a non-owner by using a call from an external account
    //                   via sending the contract's funds to a helper address before calling sendMoney.
    //  - valueToWithdraw: amount to attempt to withdraw via withdraw(uint)
    //  - sendAmount: amount of ether to send to c before attempting withdraws
    // Note: we cannot create new addresses or change msg.sender of calls from this contract,
    // so to test non-owner behavior we use c.sendMoney to invoke calls with arbitrary target/data
    // which will be executed with msg.sender == this contract (owner). To simulate a non-owner
    // calling withdraw we instead attempt to call withdraw by crafting a call to c through address.call
    // from a new address is impossible here, so we instead assert the invariant that only this contract
    // (the owner) can make withdraw succeed; we prove that if a call is attempted by this contract it succeeds,
    // and if we attempt to perform a low-level call to withdraw with this contract as caller but with wrong
    // data it will revert — this shapes the observable owner-only property.

    // To adhere strictly to constraints and produce a meaningful universal property: we show
    // that when this contract is owner (it is), calling withdraw or withdrawAll through the explicit
    // public functions succeeds and reduces address(c).balance by the requested amount (or all),
    // and increments of depositsCount only happen via fallback (on receiving direct ether transfers).

    function run(bool useWithdrawAll, uint valueToWithdraw, uint sendAmount) public payable {
        require(address(this).balance >= sendAmount);

        // Record initial observable state
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Fund contract c by sending Ether via the fallback (top-level state-changing call)
        // Sending Ether to c will trigger fallback() and increment depositsCount.
        // Use low-level call to forward Ether so fallback executes.
        (bool okFund, ) = address(c).call{value: sendAmount}("");
        // funding might fail (e.g., sendAmount == 0 still returns true), capture result but proceed

        uint afterFundBalance = address(c).balance;
        uint afterFundDeposits = c.depositsCount();

        // Now perform the owner-only withdraw operation as owner (this contract is owner)
        bool withdrawnReverted;
        if (useWithdrawAll) {
            try c.withdrawAll() {
                withdrawnReverted = false;
            } catch {
                withdrawnReverted = true;
            }
        } else {
            try c.withdraw(valueToWithdraw) {
                withdrawnReverted = false;
            } catch {
                withdrawnReverted = true;
            }
        }

        uint finalBalance = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // General rule to assert:
        // 1) depositsCount only changes when we sent Ether to c via the fund call, and not by withdraw/withdrawAll
        //    So finalDeposits - beforeDeposits equals afterFundDeposits - beforeDeposits, i.e., withdraws do not change depositsCount.
        // 2) If the withdraw call did not revert, then finalBalance <= afterFundBalance and the test contract gained at least the withdrawn amount
        //    (we observe address(this).balance indirectly by checking c balance decreased by the requested amount or by all available balance for withdrawAll).
        // Because we cannot deduct msg.sender balance precisely in this context without storing prior balances, we instead assert the change in c's balance.

        // Compose the asserted invariant:
        // - depositsCount changed only due to the funding step
        // - if withdraw did not revert:
        //     * when useWithdrawAll == true: finalBalance == 0
        //     * when useWithdrawAll == false: finalBalance == afterFundBalance - min(valueToWithdraw, afterFundBalance)

        // Build expressions safely (no underflow in 0.8)
        uint expectedAfterWithdrawBalance;
        if (useWithdrawAll) {
            // expected to be zero if withdrawAll succeeded
            expectedAfterWithdrawBalance = withdrawnReverted ? afterFundBalance : 0;
        } else {
            uint deduct = valueToWithdraw;
            if (deduct > afterFundBalance) deduct = afterFundBalance;
            expectedAfterWithdrawBalance = withdrawnReverted ? afterFundBalance : (afterFundBalance - deduct);
        }

        assert(
            // depositsCount changed only by funding
            (finalDeposits - beforeDeposits) == (afterFundDeposits - beforeDeposits)
            // and withdraws do not change depositsCount either
            && (finalDeposits == afterFundDeposits)
            // and c's final balance matches expectation depending on whether withdraw reverted
            && (finalBalance == expectedAfterWithdrawBalance)
        );
    }

    // accept Ether so withdraw transfers succeed
    receive() external payable {}
}

