contract InvMutTest {
    C c;
    address payable owner;

    constructor(C _c) {
        c = _c;
        // The deployer of C was msg.sender when C was deployed; per problem statement,
        // the checker deploys a fresh C and then deploys this test passing that C.
        // In that deployment, this contract was not the deployer of C, so owner = c.owner()
        owner = payable(c.owner());
    }

    // Single public function with inputs that the checker will vary.
    // amount: amount of wei to send into fallback of c before testing withdraws
    // withdrawAmount: amount to attempt to withdraw
    // callAsOwner: boolean indicating whether we should attempt withdraw as owner (true) or as non-owner (false)
    function run(uint amount, uint withdrawAmount, bool callAsOwner) public payable {
        require(true);
        // To send Ether to c, ensure this contract has enough balance
        if (amount > 0) {
            require(address(this).balance >= amount);
            // send Ether to c's fallback by calling with empty data
            (bool ok,) = address(c).call{value: amount}("\x00");
            // fallback increments depositsCount on any payable call; we don't require ok because fallback doesn't revert
        }

        // Record before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;
        uint beforeBalanceThis = address(this).balance;

        bool revertedWithdraw;
        // Decide who calls withdraw: if callAsOwner is true, we need to simulate owner calling.
        // We cannot change msg.sender of calls from this contract, but we can use c.sendMoney to make c call itself
        // However, c.sendMoney requires onlyOwner, so only the owner can trigger an internal call from c.
        // To test both owner and non-owner behavior of withdraw, we take two approaches:
        // - If callAsOwner == true: have owner (externally) call withdraw via invoking c.withdraw through this contract by first ensuring this contract is owner — but we cannot change owner.
        // Instead we will emulate: if callAsOwner == true and this contract is the owner according to c.owner(), then call withdraw directly; otherwise attempt withdraw and capture revert.

        // Attempt withdraw and catch revert
        try c.withdraw{value: 0}(withdrawAmount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        // Read after-values
        uint afterDeposits = c.depositsCount();
        uint afterBalanceC = address(c).balance;
        uint afterBalanceThis = address(this).balance;

        // The general property we assert:
        // - If this contract is the owner (c.owner() == address(this)), then withdraw must not revert and
        //   the contract's balance must decrease by withdrawAmount (or to zero if insufficient) and this contract's balance increase accordingly.
        // - If not owner, withdraw must revert and there must be no change to c.depositsCount and no Ether moved between c and this.

        bool iAmOwner = (c.owner() == address(this));

        if (iAmOwner) {
            // When owner called withdraw, it should not revert
            // Also depositsCount shouldn't change because withdraw doesn't modify it
            // Ether movement: c balance decreased by delta = min(withdrawAmount, beforeBalanceC)
            uint expectedWithdrawn = withdrawAmount;
            if (withdrawAmount > beforeBalanceC) {
                expectedWithdrawn = beforeBalanceC;
            }
            assert(revertedWithdraw == false && afterDeposits == beforeDeposits && afterBalanceC + expectedWithdrawn == beforeBalanceC && afterBalanceThis == beforeBalanceThis + expectedWithdrawn);
        } else {
            // Non-owner: withdraw must revert, and no state or ether changes
            assert(revertedWithdraw == true && afterDeposits == beforeDeposits && afterBalanceC == beforeBalanceC && afterBalanceThis == beforeBalanceThis);
        }
    }

    // Allow this test contract to receive refunds from c.transfer calls when it is the owner
    receive() external payable {}
}

