contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking inputs
    function run(address target, uint value, bytes memory data, uint withdrawValue) public payable {
        require(true);

        // read observable before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;

        // 1) Try to send Ether to c's fallback by calling sendMoney on c (onlyOwner) which will invoke call on target
        // We must call c.sendMoney as a top-level statement. It may revert if this contract is not owner.
        bool sendReverted;
        try c.sendMoney(target, value, data) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        // 2) Try withdraw and observe whether it reverts; capture revert flag
        bool withdrawReverted;
        try c.withdraw(withdrawValue) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // 3) Try withdrawAll and capture revert flag
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // read after-values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;
        uint afterMyBalance = address(this).balance;

        // General rule asserted: if withdraw did not revert then the contract's balance decreased by at least withdrawValue
        // and this contract's balance increased by at least withdrawValue. If withdraw reverted, balances must be unchanged by withdraw.
        // Because withdrawAll withdraws the full balance, if withdrawAll did not revert then c.balance became zero and this contract's
        // balance increased by the same amount. Also, depositsCount increases only if fallback executed (which requires a successful call to fallback).

        // We cannot precisely separate effects of sendMoney vs fallback of c vs target receiving funds, but we can assert consistency:
        // - If withdraw succeeded then afterBalance + withdrawValue <= beforeBalance (use <= to be safe if multiple withdrawals); and afterMyBalance >= beforeMyBalance + (withdrawReverted ? 0 : withdrawValue)
        // - If withdrawAll succeeded then afterBalance == 0 and afterMyBalance >= beforeMyBalance + (beforeBalance - afterBalance)

        assert(
            (withdrawReverted
                ? (afterBalance == beforeBalance && afterMyBalance == beforeMyBalance)
                : (afterBalance + withdrawValue <= beforeBalance && afterMyBalance >= beforeMyBalance + withdrawValue)
            )
            &&
            (withdrawAllReverted
                ? true
                : (afterBalance == 0 && afterMyBalance >= beforeMyBalance + (beforeBalance))
            )
        );
    }

    receive() external payable { }
}
